function nav(path){location.hash=path;}
const drafts=new DraftController(repo);let editorMessage='変更は自動保存されます';
function storageStatus(state){const el=document.querySelector('#save-status');if(!el)return;el.dataset.error=String(!!state.problem);el.textContent=state.problem|| (state.migrationMessage?.includes('転送中')?state.migrationMessage:null)|| (state.pending?'保存中…':state.lastSaved?'共通データストアに自動保存済み':'Application Storage · 接続済み');}
