function editorIssue(i){if(!i.displayText||!i.definitions.length)return 'ExpressionとEnglish Definitionを入力してください';for(const e of i.examples){if(!e.text)return '空の例文を入力するか削除してください';if(e.cloze&&!validCloze(e))return 'Clozeの文字列と開始位置を確認してください';if(e.clozeApproved&&makeQuestion({...i,examples:[e]},'cloze-select').unavailable)return 'Clozeの選択肢を確認してください';}if(i.questionSettings.recognitionApproved&&makeQuestion(i,'recognition').unavailable)return 'Recognitionの選択肢を確認してください';return null;}
drafts.validate=editorIssue;
