async function home(){const s=await repo.stats(),recent=await repo.list({},1,4),weak=await repo.list({weak:true},1,3),batches=(await repo.all('batches')).sort((a,b)=>b.at.localeCompare(a.at));
 return heading('Your learning space','出会った英語を、使える英語へ。','少しずつ、あなたの言葉にしていきましょう。',linkbtn(icon('plus',15)+' 教材を追加','#import'))+
 `<section class="hero"><div><div class="eyebrow">A LITTLE PRACTICE, EVERY DAY</div><h2>Your words.<br>Ready for the real world.</h2><p>${s.active?`今日は${s.due}件が復習のタイミングです。<br>覚えた表現を、もう一度思い出してみましょう。`:'まずは、あなたの英語をここに。<br>サンプル教材またはお手持ちのファイルで始められます。'}</p><div class="actions">${s.active?linkbtn('復習を始める '+icon('arrow',16),'#study?kind=review',true)+linkbtn('新しい表現を学ぶ','#study?kind=new'):btn('サンプル教材で始める '+icon('arrow',16),'sample',true)+linkbtn('ファイルをImport','#import')}</div></div><div class="hero-right"><div class="ring" style="--p:${s.percent||0}"><div class="ring-label"><strong>${pct(s.percent)}</strong><small>MASTERY</small></div></div><div class="legend"><div><b>${s.mastered}<span style="font-size:14px;color:#819073"> / ${s.active}</span></b>自分で使える表現</div><div style="color:#789068;margin-top:5px">${icon('leaf',13)} Your vocabulary, growing.</div></div></div></section>`+
 `<div class="stats-grid">${stat('Review due',s.due,'今日までの復習対象','clock')}${stat('New expressions',s.new,'これから学ぶ表現','library')}${stat('Weak items',s.weak,'苦手な表現をもう一度','weak')}${stat('Today’s practice',s.today.correct+s.today.incorrect,'今日の確定回答数','check')}</div>`+
 `<div class="two-col"><div>${panel('Recently added',recent.items.length?itemRows(recent.items):empty('あなたのLibraryを作りましょう','サンプルも通常のImport手順で追加されます。'),`<a class="textlink" href="#library">すべて見る ${icon('arrow',13)}</a>`)}${panel('Focus on your weak items',weak.items.length?itemRows(weak.items):empty('今のところ苦手な表現はありません','学習すると、復習したい表現がここに集まります。'),`<a class="textlink" href="#study?kind=weak">集中復習 ${icon('arrow',13)}</a>`)}</div><div>${panel('Study activity',`<div class="panel-body">${bars(s)}<div class="activity-legend"><span>過去7日間の回答</span><a href="#dashboard">進捗を見る →</a></div></div>`,'<small>LAST 7 DAYS</small>')}${panel('Latest import',batches[0]?`<div class="panel-body"><div class="item-word">${esc(batches[0].fileName)}</div><p class="hint">${date(batches[0].at)} · 新規 ${batches[0].imported} · 更新 ${batches[0].updated}</p>${batches[0].errors?`<a href="#data" class="badge weak">${batches[0].errors}件のエラーを確認</a>`:'<span class="badge Mastered">Import completed</span>'}</div>`:empty('まだImportはありません','Excel・CSVに対応しています。'))}</div></div>`;
}
