async function readFile(file,isSample=false){if(file.size>20*1024*1024)throw Error('20MBを超えるファイルは分割してImportしてください。');toast('ファイルを読み込んでいます…');const fileType=file.name.toLowerCase().endsWith('.csv')?'CSV':'XLSX';let sheets;
 if(fileType==='CSV'){const enc=document.querySelector('[name="csv-encoding"]')?.value||'utf-8',delimiter=document.querySelector('[name="csv-delimiter"]')?.value||',';sheets=[{name:'CSV',rows:parseCSV(new TextDecoder(enc,{fatal:true}).decode(await file.arrayBuffer()),delimiter)}];}
 else{const buffer=await file.arrayBuffer();sheets=await new Promise((resolve,reject)=>{const w=new Worker(new URL('./import-worker.js',import.meta.url)),timer=setTimeout(()=>{w.terminate();reject(Error('読み取りに時間がかかっています。ファイルを分割してお試しください。'));},60000);w.onmessage=e=>{clearTimeout(timer);w.terminate();if(e.data.error)reject(Error(e.data.error));else resolve(e.data.sheets);};w.onerror=e=>{clearTimeout(timer);w.terminate();reject(Error('Excelを読み取れませんでした。XLSX形式を確認してください。'));};w.postMessage({buffer},[buffer]);});}
 if(!sheets.some(s=>s.rows.length>1))throw Error('ヘッダーと教材行のあるシートがありません。');
 const previous=(await repo.all('batches')).find(b=>b.fileName===file.name);
 importState={fileName:file.name,fileType,isSample,sheets,sheetIndex:Math.max(0,sheets.findIndex(s=>autoMap(s.rows[0]||[]).expression!=='')),headerRow:0,stage:'mapping',datasetId:previous?.datasetId||''};importState.mapping=autoMap(sheets[importState.sheetIndex].rows[0]);await saveImportDraft();if(getRoute().name!=='import')nav('import');else await render();
}
async function makePreview(form){const f=new FormData(form),im=importState;for(const k of Object.keys(FIELDS))im.mapping[k]=String(f.get('map_'+k)||'');if(im.mapping.expression===''||im.mapping.definition==='')throw Error('ExpressionとEnglish Definitionの列を指定してください。');
 im.datasetId=String(f.get('dataset')||'')||im.datasetId||uid();im.delimiter=String(f.get('multiDelimiter')||' / ');const sheet=im.sheets[im.sheetIndex],headers=sheet.rows[im.headerRow];
 if(f.get('mappingName'))await repo.put('mappings',{id:uid(),name:String(f.get('mappingName')),headers,mapping:im.mapping,delimiter:im.delimiter,at:now(),version:1});
 im.rows=sheet.rows.slice(im.headerRow+1).map((row,n)=>({row,sourceRow:n+im.headerRow+2})).filter(r=>r.row.some(v=>String(v).trim())).map(({row,sourceRow})=>({...rowToItem(row,headers,im.mapping,{fileName:im.fileName,fileType:im.fileType,datasetId:im.datasetId,sheet:sheet.name,delimiter:im.delimiter}),sourceRow}));
 if(!bank)bank=[];toast('データを検証し、重複候補を確認しています…');im.rows=await previewImport(repo,im.rows,bank);im.stage='preview';im.page=1;await saveImportDraft();await render();
}
async function study(params){
 if(!session){const s=await repo.stats(),saved=(await repo.all('sessions')).filter(x=>x.status==='running').sort((a,b)=>b.at.localeCompare(a.at))[0];return heading('Daily practice','今日の学習を始める','思い出す練習を、少しずつ積み重ねましょう。')+`<div class="study-wrap">${saved?notice(`中断したセッションがあります。 ${btn('再開する','resume-session',false,`data-id="${saved.id}"`)}`):''}${panel('Study setup',`<form id="start-session" class="panel-body"><div class="field"><label>学習する教材</label>${select('kind',[{value:'review',label:`期限が来た復習 (${s.due})`},{value:'new',label:`新しい教材 (${s.new})`},{value:'weak',label:`Weak items (${s.weak})`},{value:'all',label:'Activeのすべて'}],params.get('kind')||(params.has('item')?'all':s.due?'review':'new'),null)}</div><div class="field"><label>学習モード</label>${select('mode',[{value:'mixed',label:'おまかせ — 習熟に合わせて切り替え'},...MODES.map(m=>({value:m,label:modeName(m)}))],params.get('mode')||'mixed',null)}</div><div class="field"><label>1回の学習量</label>${select('limit',['5','10','20','50'],'10',null)}</div><input type="hidden" name="itemId" value="${esc(params.get('item')||'')}">${params.has('item')?notice('選択した1件の教材を練習します。'):''}<button type="submit" class="btn primary">学習を始める ${icon('arrow',16)}</button><hr><p class="hint">Recognition：定義を選ぶ<br>Cloze Select：例文の空欄を選択肢で補う<br>Cloze Input：例文の空欄を自力で入力<br>Recall：定義から表現を思い出す<br>Production：新しい文を作り、自分で成功／失敗を判定</p></form>`)}</div>`;}
 if(session.index>=session.queue.length)return sessionSummary();
 const {item,question:q}=session.queue[session.index],answered=session.currentResult,response=session.response||'';
 return `<div class="study-wrap"><div class="study-bar"><span>${esc(modeName(q.mode))} <span class="text-muted">/ ${session.index+1} of ${session.queue.length}</span></span>${btn('ここで終了','finish-session')}</div><div class="progress" style="margin-bottom:24px"><span style="width:${100*session.index/session.queue.length}%"></span></div><div class="study-card"><div class="actions" style="justify-content:space-between"><span class="eyebrow">${esc(modeName(q.mode))}</span>${badge(item.type)}</div><div class="question">${esc(q.prompt)}</div><p class="sub">${esc(q.sub)}</p>${!answered&&q.hint?(q.mode==='cloze-select'?`<p class="notice">Meaning: ${esc(q.hint)}</p>`:`<details><summary>英語のヒントを見る</summary><p class="hint">${esc(q.hint)}</p></details>`):''}${!answered&&item.state.status==='New'&&!session.learnedIds?.includes(item.id)?`<details style="margin-bottom:18px"><summary>初めての表現を先に確認する</summary><p>${esc(item.displayText)}</p><p class="hint">${esc(item.definitions[0])}</p>${item.examples.slice(0,1).map(e=>`<p class="hint">${esc(e.text)}</p>`).join('')}${btn('内容を確認した','learn-preview',false,`data-id="${item.id}"`)}</details>`:''}${!answered?`<form id="answer-form">${q.choices?`<div class="choices">${q.choices.map((c,j)=>`<button type="button" class="choice ${response===c?'selected':''}" data-action="choose" data-value="${esc(c)}"><b>${String.fromCharCode(65+j)}</b><span>${esc(c)}</span></button>`).join('')}</div>`:`<div class="field">${q.mode==='production'?`<textarea class="answer-input" name="response" rows="4" placeholder="Write your own sentence…" aria-label="自分の英文">${esc(response)}</textarea>`:`<input class="answer-input" name="response" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Type your answer…" aria-label="英語で回答" value="${esc(response)}">`}</div>`}<div class="study-bottom">${btn('スキップ','skip')}<button type="submit" class="btn primary">${q.mode==='production'?'自己判定に進む':'回答を確認する'} ${icon('arrow',15)}</button></div></form>${q.mode==='production'&&session.productionDraft?`<div class="result"><strong>自分の英文をチェック</strong><p>${esc(session.productionDraft)}</p><ul class="checklist"><li>Targetを使えたか</li><li>意味・文法・場面が自然か</li><li>元の例文をそのまま写していないか</li></ul><div class="actions">${btn('成功した','production-grade',true,'data-correct="true"')}${btn('まだ難しかった','production-grade',false,'data-correct="false"')}</div><p class="hint">AI採点ではありません。自己判定として記録します。</p></div>`:''}`:
 `<div class="result ${answered.correct?'':'incorrect'}"><strong>${icon(answered.correct?'check':'weak',20)} ${answered.correct?'Correct':'Incorrect'}</strong><p>あなたの回答：${esc(answered.response)}</p>${q.mode==='production'?'<p class="hint">自己判定を記録しました。</p>':`<p>正解：${esc(q.answers[0])}</p>`}<span class="hint">保存済み · 次回 ${date(answered.nextReview)}</span></div><div class="explanation"><h3>Target</h3><p>${esc(item.displayText)}${audioButton(item.displayText.replace(/~/g,''))}</p><h3>Definition</h3><p>${esc(item.definitions[0])}</p><h3>Related expressions</h3><p>${item.related.map(esc).join(' / ')||'—'}</p><h3>Examples</h3>${item.examples.slice(0,3).map(e=>`<p>${esc(e.text)}${audioButton(e.text)}</p>`).join('')}<h3>Source</h3><p>${item.sources.map(s=>esc(s.name)).join(' · ')}</p><p class="hint">現在：${esc(answered.status)} · 参考Score：${answered.score??'計測中'}</p>${answered.status==='Mastered'&&!answered.correct?notice(`Masteredのままです。使えなかった場合は解除できます。 ${btn('Masteredを解除','study-unmaster',false,`data-id="${item.id}"`)}`,'warn'):''}<label class="check"><input type="checkbox" data-change="study-mastered" data-id="${item.id}" ${answered.status==='Mastered'?'checked':''}>I have mastered this expression</label><div class="study-bottom"><a class="textlink" href="#item/${item.id}">教材の詳細</a>${btn(session.index+1===session.queue.length?'結果を見る':'次の表現へ '+icon('arrow',15),'next',true)}</div></div>`}</div><p class="footer-note">Question first. Understanding next.<br>回答は1問ずつ、アプリ共通ストレージに保存されます。</p>${session.unavailable.length?`<details><summary>出題できなかった教材 ${session.unavailable.length}件</summary>${session.unavailable.slice(0,15).map(i=>`<p class="hint"><a href="#edit/${i.id}">${esc(i.expression)}</a> — ${esc(i.reason)}</p>`).join('')}</details>`:''}</div>`;
}
async function persistSession(status='running'){if(!session)return;const value={...structuredClone(session),status,updatedAt:now()};repo.writeJournal('session',value);await repo.put('sessions',value);}
async function startSession(form){const f=new FormData(form);session=await prepareSession(repo,{kind:String(f.get('kind')),mode:String(f.get('mode')),limit:Number(f.get('limit')),itemId:String(f.get('itemId')||'')});session.currentResult=null;session.newlyMastered=[];
 if(!session.queue.length){const unavailable=session.unavailable;session=null;modal('学習できる教材がありません',`<p>選択した条件に合う教材がないか、このモードの問題設定が未完了です。</p>${unavailable.slice(0,8).map(i=>`<p><a href="#edit/${i.id}" data-action="close-on-link">${esc(i.expression)}の問題設定を開く</a><br><span class="hint">${esc(i.reason)}</span></p>`).join('')}<div class="actions">${linkbtn('教材を確認','#library')}${btn('閉じる','close-modal')}</div>`);return;}
 await persistSession();await render();}
async function answerSession(response,correct){const {item,question:q}=session.queue[session.index];if(session.currentResult)return;
 const result={id:q.id,itemId:item.id,sessionId:session.id,mode:q.mode,response,correct,at:now(),grading:q.mode==='production'?'self':'exact-normalized',question:{prompt:q.prompt,answers:q.answers,exampleId:q.exampleId,contentRevision:q.revision},policyVersion:1};
 const saved=await repo.answer(result);const state=saved.state||await repo.get('states',item.id);session.currentResult={...result,nextReview:state.nextReview,status:state.status,score:state.score};if(!session.answers.some(r=>r.id===result.id))session.answers.push(session.currentResult);session.productionDraft=null;await persistSession();changed();await render();}
async function sessionSummary(){const s=await repo.stats(),a=session.answers,c=a.filter(r=>r.correct).length,p=a.filter(r=>r.mode==='production');session.finishedAt??=now();await persistSession('completed');
 return `<div class="study-wrap"><div class="summary-title"><div class="eyebrow">Session complete</div><h2>A little more yours.</h2><p class="hint">今日の一歩が、使える英語につながります。</p></div><div class="stats-grid">${stat('Reviewed',a.length,'確定回答数','library')}${stat('Correct',c,'正答','check')}${stat('Incorrect',a.length-c,'もう一度練習','weak')}${stat('Accuracy',a.length?pct(100*c/a.length):'—','今回の正答率','target')}</div>${panel('Your progress',`<div class="panel-body"><dl class="meta"><dt>Overall Mastery</dt><dd>${pct(session.initialMastery)} → ${pct(s.percent)}</dd><dt>Production</dt><dd>${p.filter(r=>r.correct).length} / ${p.length} 成功</dd><dt>Newly Mastered</dt><dd>${session.newlyMastered?.length||0}</dd><dt>スキップ</dt><dd>${session.skipped||0}</dd></dl>${session.newlyMastered?.length?`<p class="hint">${session.newlyMastered.map(x=>esc(x.text)).join(' / ')}</p>`:''}<hr><div class="actions">${btn('もう一度学習する','new-session',true)}${btn('Homeへ戻る','session-home')}</div></div>`)}${session.unavailable.length?notice(`${session.unavailable.length}件は問題設定が必要なため、このモードの出題対象から外れました。Libraryの詳細画面から設定できます。`,'warn'):''}</div>`;
}
async function dashboard(params){const range=params.get('range')||'30',axis=params.get('axis')||'categories',s=await repo.stats(range),total=s.period.correct+s.period.incorrect,groups=s[axis]||s.categories;
 return heading('Review dashboard','学びの積み重ねを見える形に。','Masteredは、あなたが「使える」と判断した表現の割合です。',linkbtn('Weakを集中復習','#study?kind=weak'))+
 `<div class="tabs">${[['7','7 Days'],['30','30 Days'],['90','90 Days'],['all','All Time']].map(([v,l])=>`<a class="${range===v?'active':''}" href="#dashboard?range=${v}&axis=${axis}">${l}</a>`).join('')}</div><div class="stats-grid">${stat('Overall mastery',pct(s.percent),`${s.mastered} / ${s.active} Active items`)}${stat('Practice',total,'期間内の回答数','library')}${stat('Accuracy',total?pct(s.period.correct/total*100):'—','期間内の正答率','check')}${stat('Production',s.period.production?pct(100*s.period.productionSuccess/s.period.production):'—',`${s.period.production}回 · 自己判定`,'study')}</div>`+
 `<div class="two-col"><div>${panel('Learning status',`<div class="panel-body">${Object.entries(s.status).map(([k,v])=>`<div class="category-row"><div class="category-top"><span>${badge(k)}</span><span>${v} items</span></div><div class="progress"><span style="width:${s.active?v/s.active*100:0}%"></span></div></div>`).join('')}<p class="hint">Archived ${s.archived} · Total ${s.active+s.archived}</p></div>`)}${panel('Mastery trend',s.trend.length?`<div class="table-scroll"><table><thead><tr><th>日付</th><th>Active</th><th>Mastered</th><th>Mastery</th></tr></thead><tbody>${s.trend.map(t=>`<tr><td>${esc(t.date)}</td><td>${t.active}</td><td>${t.mastered}</td><td>${pct(t.percent)}</td></tr>`).join('')}</tbody></table></div>`:empty('まだ変化はありません','追加・Mastered・Archiveの履歴から推移を記録します。'))}</div><div>${panel('Study activity',`<div class="panel-body">${bars(s,7)}<p class="hint">直近7日間の回答数</p><dl class="meta"><dt>新規追加</dt><dd>${s.period.added}</dd><dt>Archive</dt><dd>${s.period.archived}</dd><dt>データ更新</dt><dd>${s.period.updated}</dd><dt>Import</dt><dd>${s.period.imports}</dd><dt>Export</dt><dd>${s.period.exports}</dd></dl></div>`)}${panel('Mastery breakdown',`<div class="panel-body"><div class="field">${select('axis',[{value:'categories',label:'Category別'},{value:'types',label:'Type別'},{value:'sources',label:'Source別'},{value:'formats',label:'Import形式別'},{value:'difficulties',label:'Difficulty別'}],axis,null,'data-change="dashboard-axis"')}</div>${Object.entries(groups).sort((a,b)=>b[1].total-a[1].total).map(([n,g])=>`<div class="category-row"><div class="category-top"><span>${esc(n)}</span><span>${g.mastered} / ${g.total} · ${pct(g.mastered/g.total*100)}</span></div><div class="progress"><span style="width:${g.mastered/g.total*100}%"></span></div></div>`).join('')||'<p class="hint">教材を追加すると表示されます。</p>'}<p class="hint">現在の所属で集計。同じ教材が複数の分類に含まれることがあります。</p></div>`)}</div></div>`;
}
async function dataPage(){const batches=(await repo.all('batches')).sort((a,b)=>b.at.localeCompare(a.at)),mappings=await repo.all('mappings'),settings=await repo.get('settings','backup'),s=await repo.stats();
 const protection=await repo.protection();const diagnostics=panel('Application persistence',`<div class="panel-body"><dl class="meta"><dt>正本の保存先</dt><dd>Application Persistent Data Store · D1</dd><dt>schemaVersion</dt><dd>${repo.metadata?.schemaVersion??'確認中'}</dd><dt>不正データの保護</dt><dd>${repo.invalidIds?.size||0}件</dd><dt>最終サーバー保存</dt><dd>${date(repo.lastSaved||repo.metadata?.updatedAt)}</dd></dl><p class="hint">Safari・ChatGPT内ブラウザとも、同じアプリの永続データを参照します。通常利用には通信が必要です。通信できない場合は空データに切り替えません。</p>${repo.migrationMessage?notice(esc(repo.migrationMessage)):''}<div class="actions">${btn('共通データを再読み込み','refresh-server')}${btn('旧ブラウザデータをJSON保存','legacy-backup')}</div><p class="hint">以前のデータがSafariにだけ残っている場合は、最初にそのSafariでアプリを開いてください。共通ストレージが空なら自動移行します。既に共通データがある場合は自動置換せず、旧データのJSONを取得できます。</p></div>`);
 return diagnostics+heading('Data management','大切な学習データを管理する。','Export・バックアップ・Import履歴をまとめて確認できます。')+notice('教材と学習履歴はアプリ共通の永続データベースに保存されています。ブラウザを変えても同じ保存済みデータを読み込みます。JSONバックアップも利用できます。')+
 `<div class="two-col"><div>${panel('Backup & restore',`<div class="panel-body"><p style="font-size:13px;line-height:1.9">教材・履歴・Mastered・復習予定・Mappingをまとめて保存します。別のブラウザへの移行にも使えます。</p><div class="actions">${btn('JSONバックアップを保存','backup',true)}</div><p class="hint">最終バックアップ：${settings?date(settings.at):'まだありません'}</p><hr><label class="field"><span>JSONから復元</span><input id="restore-file" type="file" accept=".json,application/json"><small>アプリ形式のバックアップ専用です。内容の確認後に現在のデータを置換します。</small></label></div>`)}${panel('Selective JSON export',`<form id="export-form" class="panel-body"><div class="form-grid"><div class="field"><label>対象</label>${select('scope',[{value:'all',label:'全データ（Archived含む）'},{value:'active',label:'Activeのみ'},{value:'mastered',label:'Masteredのみ'},{value:'weak',label:'Weakのみ'}],'all',null)}</div><div class="field"><label>Category</label>${select('category',s.options.categories)}</div><div class="field"><label>Source</label>${select('source',s.options.sources)}</div><div class="field"><label>Import Batch</label>${select('batch',s.options.batches)}</div></div><div class="stack"><label class="check"><input name="history" type="checkbox" checked>学習履歴を含む</label><label class="check"><input name="references" type="checkbox" checked>外部参照・Import情報を含む</label></div><button class="btn" type="submit" style="margin-top:18px">JSON Export</button><p class="hint">完全復元用には上の「JSONバックアップ」を使用してください。</p></form>`)}</div><div>${panel('Mapping templates',mappings.length?mappings.map(m=>`<div class="item-row"><div><div class="item-word">${esc(m.name)}</div><small>${date(m.at)} · version ${m.version}</small></div>${btn('削除','delete-mapping',false,`data-id="${m.id}"`)}</div>`).join(''):empty('テンプレートはまだありません','Importの列対応画面で名前を付けて保存できます。'))}${panel('Archived items',`<div class="panel-body"><div class="stat-value">${s.archived}</div><p class="hint">教材と学習履歴を残したまま、学習対象から除外しています。</p>${linkbtn('Archivedを確認','#library?archive=archived')}</div>`)}${panel('About this app',`<div class="panel-body"><p class="hint">MVP 1.2 · Application schema 1<br>Review policy 1 · Asia/Tokyo<br>Excel解析：SheetJS CE 0.20.3 (Apache-2.0)<br>音声：利用可能なブラウザ標準の英語音声</p><a class="textlink" href="./application-persistence-report.html" target="_blank" rel="noopener">永続化の検証結果 ↗</a><hr><a class="textlink" href="./acceptance-report.html" target="_blank" rel="noopener">実装・検証レポートを開く ↗</a></div>`)}</div></div>`+
 panel('Import history',batches.length?`<div class="table-scroll"><table><thead><tr><th>FILE / DATE</th><th>形式</th><th>新規</th><th>更新</th><th>Skip</th><th>Error</th><th>状態</th></tr></thead><tbody>${batches.map(b=>`<tr><td><strong>${esc(b.fileName)}</strong><span class="definition">${date(b.at)} · ${esc(b.sheet||'')}</span><details><summary>Import ID</summary><span class="hint">${esc(b.id)}<br>Dataset: ${esc(b.datasetId)}</span></details></td><td>${esc(b.fileType)}</td><td>${b.imported}</td><td>${b.updated}</td><td>${b.skipped}</td><td>${b.errors?btn(String(b.errors)+'件を確認','import-errors',false,`data-id="${b.id}"`):'0'}</td><td>${badge(b.status)}${b.failure?`<p class="error-list">${esc(b.failure)}</p>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Import履歴はまだありません','ファイルを取り込むと、ここに結果が残ります。'));
}
async function render(){const token=++routeToken,{name,id,params}=getRoute();try{let content;if(repo.readOnly){root.innerHTML=shell('data',notice(esc(repo.problem),'error')+btn('保存データを救出する','raw-backup',true));return;}
 if(name==='home')content=await home();else if(name==='library')content=await library(params);else if(name==='item')content=await detail(id);else if(name==='import')content=await importPage(params);else if(name==='dashboard')content=await dashboard(params);else if(name==='data')content=await dataPage();else if(name==='study')content=await study(params);else if(name==='edit'){if(!editor||editor.id!==id){const i=await repo.aggregate(id);if(!i)throw Error('教材が見つかりません');editor={...i,existing:true};}content=editorView(editor);}else content=empty('ページが見つかりません','Homeからお進みください。',linkbtn('Homeへ','#home'));
 if(token!==routeToken)return;root.innerHTML=shell(name,content);storageStatus(repo);document.title=(name==='study'?'Study · ':'')+'Personal Vocabulary Trainer';
 }catch(e){if(token===routeToken)root.innerHTML=shell(name,notice(esc(e.message),'error')+linkbtn('Homeへ','#home'));error(e);}}
async function act(a,el){const {id,on,index}=el.dataset;
 switch(a){
 case 'refresh-server':await repo.open();await render();break;
 case 'legacy-backup':{const legacy=new IndexedDBRepository();try{await legacy.open();download('legacy-browser-backup-'+day()+'.json',await legacy.exportData());}finally{legacy.db?.close();}break;}
 case 'raw-backup':download('vocabulary-recovery.json',await repo.rawBackup());break;
 case 'audio':{if(!globalThis.speechSynthesis)return;const u=new SpeechSynthesisUtterance(el.dataset.text);u.lang='en-US';u.rate=.9;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)u.voice=voice;speechSynthesis.cancel();speechSynthesis.speak(u);break;}
 case 'page':{const r=getRoute();r.params.set('page',el.dataset.page);nav('library?'+r.params);break;}
 case 'archive':await repo.archive(id,on==='true');changed();toast(on==='true'?'Archiveしました':'学習対象に戻しました');await render();break;
 case 'add-example':editor=readEditor();editor.examples.push({id:uid(),text:'',type:'Personal',isActive:true,acceptedVariants:[],distractors:[],cloze:null});await drafts.capture(editor);await render();break;
 case 'remove-example':editor=readEditor();editor.examples.splice(Number(index),1);await drafts.capture(editor);await render();break;
 case 'manual-merge':await saveEditor('merge');break;
 case 'manual-new':await saveEditor('new');break;
 case 'close-modal':document.querySelector('#modal').close();break;
 case 'close-on-link':document.querySelector('#modal').close();break;
 case 'reset-import':importState=null;await saveImportDraft();await render();break;
 case 'apply-header':{const n=Number(document.querySelector('[name="headerRow"]').value)-1;if(!Number.isInteger(n)||n<0||n>=importState.sheets[importState.sheetIndex].rows.length-1)throw Error('有効なヘッダー行を指定してください');importState.headerRow=n;importState.headerRowInput=n+1;importState.mapping=autoMap(importState.sheets[importState.sheetIndex].rows[n]);await render();break;}
 case 'back-mapping':importState.stage='mapping';await render();break;
 case 'import-page':importState.page=Number(el.dataset.page);await render();break;
 case 'commit-import':{const im=importState;im.batchId??=uid();await saveImportDraft();im.result=await commitImport(repo,im.rows,{id:im.batchId,fileName:im.fileName,fileType:im.fileType,datasetId:im.datasetId,sheet:im.sheets[im.sheetIndex].name,mapping:im.mapping},(n,t)=>{const p=document.querySelector('#import-progress');if(p)p.textContent=`保存中 ${n} / ${t}`;});im.stage='done';await saveImportDraft();changed();toast('Importが完了しました');await render();break;}
 case 'learn-preview':await repo.learn(id);session.learnedIds??=[];session.learnedIds.push(id);await persistSession();changed();await render();break;
 case 'choose':session.response=el.dataset.value;await persistSession();document.querySelectorAll('.choice').forEach(x=>x.classList.toggle('selected',x===el));break;
 case 'production-grade':await answerSession(session.productionDraft,on==='true'||el.dataset.correct==='true');break;
 case 'skip':session.skipped++;session.index++;session.currentResult=null;session.response='';session.productionDraft=null;await persistSession();await render();break;
 case 'next':if(!session.currentResult)return;session.index++;session.currentResult=null;session.response='';session.productionDraft=null;await persistSession();await render();break;
 case 'finish-session':session.index=session.queue.length;await render();break;
 case 'new-session':session=null;nav('study');await render();break;
 case 'session-home':session=null;nav('home');break;
 case 'resume-session':session=await repo.get('sessions',id);await render();break;
 case 'study-unmaster':await repo.markMastered(id,false);session.currentResult.status=(await repo.get('states',id)).status;session.newlyMastered=session.newlyMastered.filter(x=>x.id!==id);await persistSession();changed();await render();break;
 case 'backup':{const data=await repo.exportData();download('vocabulary-backup-'+day()+'.json',data);await repo.put('settings',{id:'backup',at:now()});await repo.put('events',{id:uid(),type:'exported',at:now()});toast('バックアップをダウンロードしました');await render();break;}
 case 'persist-storage':{const ok=await navigator.storage?.persist?.();toast(ok?'ブラウザに永続保存が許可されました':'永続化は許可されませんでした。JSONバックアップをご利用ください。');break;}
 case 'confirm-restore':{if(document.querySelector('#restore-confirm')?.value!=='RESTORE')throw Error('確認欄に RESTORE と入力してください。');await drafts.clear();await repo.restore(restorePending);restorePending=null;repo.clearJournal('session');session=null;editor=null;importState=null;await repo.inspectIntegrity();document.querySelector('#modal').close();changed();toast('バックアップを復元しました');await render();break;}
 case 'delete-mapping':await repo.remove('mappings',id);toast('Mappingを削除しました');await render();break;
 case 'import-errors':{const rows=await repo.importErrors(id);modal('Importのエラー行',`<p>元ファイルを修正して再Importできます。または、行の値を手動追加画面で修正して登録できます。</p>${rows.slice(0,30).map((r,n)=>`<div class="inline-edit"><strong>${r.row}行目</strong><p class="error-list">${r.errors.map(esc).join('<br>')}</p><pre>${esc(JSON.stringify(r.raw,null,2))}</pre>${btn('修正して登録','repair-row',false,`data-batch="${id}" data-row="${r.id}"`)}</div>`).join('')}<p class="hint">表示は先頭30件。全エラーはJSONバックアップのImport Recordに保持されます。</p>`);break;}
 case 'repair-row':{const r=await repo.get('importRows',el.dataset.row),b=await repo.get('batches',el.dataset.batch),keys=Object.keys(r.raw),item=rowToItem(Object.values(r.raw),keys,b.mapping,{fileName:b.fileName,fileType:b.fileType,datasetId:b.datasetId,sheet:b.sheet}).item;editor={...item,repairRecordId:r.id};document.querySelector('#modal').close();nav('import?tab=manual');break;}
 }
 if(['apply-header','back-mapping','import-page'].includes(a))await saveImportDraft();
}
async function guarded(fn,el){if(busy)return;busy=true;const old=el?.disabled;if(el&&'disabled'in el)el.disabled=true;try{await fn();if(!protectionRequested){protectionRequested=true;repo.protection(true).catch(()=>{});}}catch(e){error(e);}finally{busy=false;if(el&&'disabled'in el)el.disabled=old||false;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.tagName!=='A')e.preventDefault();guarded(()=>act(el.dataset.action,el),el);});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;guarded(async()=>{
 if(form.id==='library-filter'){const params=new URLSearchParams();for(const [k,v] of new FormData(form))if(v)params.set(k,String(v));nav('library?'+params);}
 if(form.id==='mapping-form')await makePreview(form);
 if(form.id==='item-editor')await saveEditor();
 if(form.id==='start-session')await startSession(form);
 if(form.id==='answer-form'){const q=session.queue[session.index].question,response=q.choices?session.response:String(new FormData(form).get('response')||'').trim();if(!response)throw Error('回答を入力または選択してください。');if(q.mode==='production'){session.productionDraft=response;await persistSession();await render();}else await answerSession(response,grade(q,response));}
 if(form.id==='export-form'){const f=new FormData(form),scope=String(f.get('scope')),filter={archive:scope==='all'?'all':'active',category:String(f.get('category')||''),source:String(f.get('source')||''),batch:String(f.get('batch')||'')};if(scope==='mastered')filter.status='Mastered';if(scope==='weak')filter.weak=true;const data=await repo.exportData(filter,{history:f.has('history'),references:f.has('references')});download('vocabulary-export-'+day()+'.json',data);await repo.put('events',{id:uid(),type:'exported',at:now()});toast('JSONをExportしました');}
 },form.querySelector('[type="submit"]'));});
document.addEventListener('change',e=>{const el=e.target;guarded(async()=>{
 if(el.id==='import-file'&&el.files[0])await readFile(el.files[0]);
 if(el.id==='restore-file'&&el.files[0]){const f=el.files[0];if(f.size>100*1024*1024)throw Error('バックアップが大きすぎます');let b;try{b=JSON.parse(await f.text());}catch{throw Error('JSONファイルを読み取れません');}const v=validateBackup(b);restorePending=b;modal('バックアップを復元',`<p>教材 <strong>${v.items}件</strong>、回答履歴 <strong>${v.records}件</strong><br>作成日 ${esc(v.exportedAt)}</p>${notice('アプリ共通の保存済みデータを、このバックアップの内容で置換します。すべてのブラウザに反映されます。必要なら先に現在のJSONバックアップを保存してください。','warn')}<div class="field"><label for="restore-confirm">置換する場合は RESTORE と入力</label><input id="restore-confirm" autocomplete="off"></div><div class="actions">${btn('置換して復元','confirm-restore',true)}${btn('キャンセル','close-modal')}</div>`);el.value='';}
 const type=el.dataset.change,id=el.dataset.id;
 if(type==='mastered'||type==='study-mastered'){await repo.markMastered(id,el.checked);changed();if(type==='study-mastered'){const s=await repo.get('states',id);session.currentResult.status=s.status;session.currentResult.nextReview=s.nextReview;session.newlyMastered??=[];if(el.checked&&!session.newlyMastered.some(x=>x.id===id))session.newlyMastered.push({id,text:session.queue[session.index].item.displayText});if(!el.checked)session.newlyMastered=session.newlyMastered.filter(x=>x.id!==id);await persistSession();}toast(el.checked?'Masteredにしました':'Masteredを解除しました');await render();}
 if(type==='weak'){await repo.markWeak(id,el.checked);changed();await render();}
 if(type==='sheet'){importState.sheetIndex=Number(el.value);importState.headerRow=0;importState.headerRowInput=1;importState.mapping=autoMap(importState.sheets[importState.sheetIndex].rows[0]);await render();}
 if(type==='mapping-template'&&el.value){const t=await repo.get('mappings',el.value);importState.delimiter=t.delimiter||' / ';const headers=importState.sheets[importState.sheetIndex].rows[importState.headerRow];importState.mapping={};for(const [k,ix] of Object.entries(t.mapping)){const header=t.headers[Number(ix)],newIx=ix===''?-1:headers.findIndex(h=>norm(h)===norm(header));importState.mapping[k]=newIx<0?'':String(newIx);}await render();}
 if(type==='dataset')importState.datasetId=el.value;
 if(type==='import-action')importState.rows[Number(el.dataset.index)].action=el.value;
 if(type==='import-target')importState.rows[Number(el.dataset.index)].targetId=el.value;
 if(['sheet','mapping-template','dataset','import-action','import-target'].includes(type))await saveImportDraft();
 if(type==='dashboard-axis'){const r=getRoute();r.params.set('axis',el.value);nav('dashboard?'+r.params);}
 },null);});
window.addEventListener('hashchange',async()=>{document.querySelector('#modal').close();try{await drafts.flush();}catch(e){error(e);}try{if(!repo.readOnly)await rememberRoute();await render();}catch(e){error(e);}window.scrollTo({top:0,behavior:'instant'});});
savedChannels&&(savedChannels.onmessage=()=>{if(['edit','import','study'].includes(getRoute().name))toast('別のタブで更新されました。保存時に最新の状態を確認します。');else render();});
window.addEventListener('pvt-storage-blocked',()=>toast('別のタブを閉じて、データベースを再読み込みしてください。'));
window.addEventListener('unhandledrejection',e=>error(e.reason));
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.closest('#item-editor')&&editor){editor=readEditor();drafts.capture(editor).catch(error);}
 if(el.closest('#answer-form')&&session&&!session.currentResult){session.response=el.value;persistSession().catch(error);}
 if(el.closest('#mapping-form')&&importState){if(el.name.startsWith('map_'))importState.mapping[el.name.slice(4)]=el.value;if(el.name==='headerRow')importState.headerRowInput=el.value;if(el.name==='mappingName')importState.mappingName=el.value;if(el.name==='multiDelimiter')importState.delimiter=el.value;saveImportDraft().catch(error);}
});
document.addEventListener('change',e=>{if(e.target.closest('#item-editor')&&editor){editor=readEditor();drafts.capture(editor).catch(error);}});
window.addEventListener('pagehide',()=>{drafts.flush().catch(()=>{});});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')drafts.flush().catch(error);else if(!['study','edit','import'].includes(getRoute().name))render();});
window.addEventListener('focus',()=>{if(!['study','edit','import'].includes(getRoute().name))render();});
