try{
 await repo.open();await repo.migrateLegacy();
 if(!repo.readOnly){const invalidCount=await repo.inspectIntegrity();if(invalidCount)toast(`${invalidCount}件の不正データを保護しています。Data Managementから救出できます。`);editor=await drafts.restore();try{await drafts.flush();}catch(e){error(e);}importState=(await repo.get('settings','import-workspace'))?.value||null;session=await restoreSession(repo);const last=await repo.get('settings','last-route');if(!location.hash&&last?.value)location.hash=last.value;}
 await render();repo.protection().catch(()=>{});
}catch(e){root.innerHTML=`<div class="loading"><h1>保存データを開けません</h1><p>既存データは削除・初期化していません。通信状態を確認して再試行してください。旧ブラウザデータの移行中に失敗した場合も元データは保持されています。</p><p>${esc(e.message)}</p><button onclick="location.reload()" class="btn">再試行</button></div>`;}
